def test_instanceproperty_forwards_fset():
    calls = []
    def setter(self, value):
        calls.append(value)
    def getter(self):
        return calls[-1]
    class C:
        prop = toolz.functoolz.instanceproperty(fset=setter)(getter)
    c = C()
    c.prop = 7
